<script lang="ts">import { MasonryItem,MasonryRoot,MasonryViewport } from '@fex-design/svelte/primitive/masonry';import Button from '@fex-design/svelte/ui/button';import { masonryItems,type MasonryDemoItem } from './data';const initial=masonryItems.slice(0,8);let items:MasonryDemoItem[]=$state([...initial]),serial=1;function add(middle=false){const item={id:`added-${serial}`,title:`新增 ${serial}`,height:120+serial%3*40};serial++;const next=[...items];next.splice(middle?Math.floor(next.length/2):next.length,0,item);items=next}</script>
<div class="grid gap-space-md"><div class="flex flex-wrap gap-space-sm"><Button size="sm" onclick={()=>add()}>末尾添加</Button><Button size="sm" variant="outline" onclick={()=>add(true)}>中间插入</Button><Button size="sm" variant="outline" onclick={()=>items=[...items].sort(()=>Math.random()-.5)}>打乱</Button><Button size="sm" variant="outline" onclick={()=>items=[...initial]}>恢复</Button></div><MasonryRoot columns={3} gap={12}><MasonryViewport>{#each items as item,index(item.id)}<MasonryItem itemKey={item.id} {index}><article class="rounded-md border border-border bg-background p-space-md" style:min-height={`${item.height/2}px`}><strong>{item.title}</strong><p class="text-xs text-muted-foreground">{item.id}</p><Button class="mt-2" size="sm" variant="outline" onclick={()=>items=items.filter(value=>value.id!==item.id)}>删除</Button></article></MasonryItem>{/each}</MasonryViewport></MasonryRoot></div>
